 {panel==='imagery'&&<>{gcov.data?.observations.length? <div className="observation-summary"><label className="imagery-source">Radar appearance<select aria-label="Radar appearance" value={gcovId} onChange={event=>chooseGcov(event.target.value)}><option value="">Optical background</option>{gcov.data.observations.map(observation=><option key={observation.id} value={observation.id}>NISAR · {observation.acquisitionDate.slice(0,10)}{gcovTracks.length>1?` · T${trackKey(observation)}`:''}</option>)}</select></label>{gcovStyle==='terrain'?<><p>Terrain colour from radar</p><span>Each date’s NISAR HH and HV, plus elevation, predict the terrain colour using a table learned from the 2025 aerial photo. Elevation is fixed, so changes between dates come only from the radar. Use the timeline to play the dates.</span></>:gcovStyle==='shaded'?<><p>Aerial photo + radar shading</p><span>Colours come from the SWISSIMAGE 2025 aerial photo, so they are not this date’s colours. Each date only brightens or darkens it by how much its HH radar differs from the mean of all dates. Use the timeline to play the dates.</span></>:gcovStyle==='natural'?<><p>Natural-like palette · from HH/HV radar classes</p><span>Strong surface scattering is painted ice-white, strong volume scattering vegetation-green, the rest rock-brown. These are approximate radar classes, not photo colours. Use the timeline to play the dates.</span></>:gcovStyle==='false'?<><p>False colour · R HH, G HV, B HH−HV · fixed stretch</p><span>Ice and snow appear purple–blue, rough rock and vegetation green–yellow. Radar colours are not natural colours. Use the timeline to play the dates.</span></>:<><p>HH backscatter · fixed −25 to 0 dB scale</p><span>Darker means weaker radar return. Transparent cells have no accepted measurement. This layer shows radar appearance.</span></>}{gcovContext&&<a className="text-link" href={`/api/science/${scenario.id}/gcov/${encodeURIComponent(gcovContext.id)}/provenance.json`} target="_blank" rel="noreferrer">Radar provenance <ExternalLink size={13}/></a>}</div>:null}{gcov.isError&&<p role="alert">Radar appearance could not be loaded. <button className="text-link" onClick={()=>gcov.refetch()}>Retry</button></p>}<div className="observation-summary">{(scenario.id==='aletsch'||flood)&&<label className="imagery-source">{gcovContext?'Optical background on return':'Image source'}<select aria-label={gcovContext?'Optical background on return':'Image source'} value={imagerySource} onChange={e=>{setImagerySource(e.target.value as typeof imagerySource);setStep(0);setBaseline(0);setPlaying(false);setBlink(false);setCompare(false);setDisplayed(null);setFrameState('loading');setCamera(null)}}>{scenario.id==='aletsch'&&<><option value="swissimage">Swiss aerial · sharper</option><option value="sentinel2">Sentinel-2 · dated captures</option></>}{flood&&<option value="sentinel2">Sentinel-2 · dated captures</option>}</select></label>}{!gcovContext&&<><strong>{aerial?'SWISSIMAGE · aerial mosaic':dated?'Sentinel-2 · natural colour':'Dated imagery'}</strong><p>{aerial?'Alps: typically 25 cm source pixels':dated?'10 m source pixels':'No dated imagery available'} · {frames.length||'…'} {aerial?'mosaic versions':dated?'dated captures':'dated captures'}<br/>{aerial?'Mosaic years · 2018–2025':dated?'27 June–14 November 2022':'No dated acquisition available'}</p><span>{aerial?'Full detail at every zoom. Mosaic image dates vary; adjacent years may reuse the same flight.':dated?'Play real captures to see floodplain change. This is optical imagery, not NISAR; water depth is not measured.':'Full detail at every zoom. Only the dated observations listed in this timeline can be played.'}</span></>}</div>{!gcovContext&&<details className="image-adjustments"><summary>Image adjustments</summary>{([{key:'brightness',label:'Highlights',min:0.5,max:1},{key:'contrast',label:'Contrast',min:-0.4,max:0.4},{key:'saturation',label:'Color',min:-1,max:0.5}] as const).map(({key,label,min,max})=><label key={key}><span>{label}<output>{Math.round(adjustments[key]*100)}%</output></span><input aria-label={label} type="range" min={min} max={max} step="0.01" value={adjustments[key]} onChange={e=>setAdjustments(v=>({...v,[key]:+e.target.value}))}/></label>)}<Button variant="ghost" size="small" onClick={()=>setAdjustments({brightness:1,contrast:0,saturation:0})}>Reset image</Button><p>Display only · original data stays unchanged.</p></details>}</>}
